const mod = 998244353n;
const N = 5000;

let factor = [];
let primes = [];

function comb(m, n) {
    let res = 1n;
    const fnm = [...factor[n]];
    for (let i = 0; i < factor[m].length; i++) {
        fnm[i] += factor[m][i];
    }
    for (let w = 1; w <= m; w++) {
        let r = 1n;
        for (let i = 0; i < primes.length; i++) {
            let pw = fnm[i] - factor[w][i] - factor[n - w][i] - factor[m - w][i];
            let p = primes[i];
            while (pw > 0) {
                if (pw & 1) {
                    r = (r * p) % mod;
                }
                p = (p * p) % mod;
                pw >>= 1;
            }
        }
        res = (res + r) % mod;
    }
    return res;
}

function main() {
    const input = require('fs').readFileSync('/dev/stdin', 'utf8').trim().split(/\s+/).map(Number);
    const abc = [input[0], input[1], input[2]];
    abc.sort((a, b) => a - b);

    const sieve = Array(N + 1).fill(false);
    sieve[0] = true;
    sieve[1] = true;
    for (let p = 2; p <= N; p++) {
        if (!sieve[p]) {
            primes.push(BigInt(p));
            for (let q = p * p; q <= N; q += p) {
                sieve[q] = true;
            }
        }
    }

    factor = Array.from({ length: N + 1 }, () => Array(primes.length).fill(0));

    for (let i = 0; i < primes.length; i++) {
        const p = Number(primes[i]);
        for (let pp = p; pp <= N; pp *= p) {
            for (let j = pp; j <= N; j += pp) {
                factor[j][i]++;
            }
        }
    }

    let a = factor[0];
    for (let idx = 0; idx < factor.length; idx++) {
        const b = factor[idx];
        for (let i = 0; i < a.length; i++) {
            b[i] += a[i];
        }
        a = b;
    }

    const res = comb(abc[0], abc[1]) * comb(abc[0], abc[2]) % mod * comb(abc[1], abc[2]) % mod;
    console.log(res.toString());
}

main();

