const MOD = 998244353;
const N = 5000;

function main() {
    const input = require('fs').readFileSync(0, 'utf-8').trim().split(/\s+/).map(Number);
    const abc = input.slice(0, 3).sort((a, b) => a - b);

    // Sieve
    const isComposite = new Array(N + 1).fill(false);
    isComposite[0] = true;
    isComposite[1] = true;
    const primes = [];
    for (let p = 2; p <= N; p++) {
        if (!isComposite[p]) {
            primes.push(p);
            if (p * p <= N) {
                for (let q = p * p; q <= N; q += p) {
                    isComposite[q] = true;
                }
            }
        }
    }

    const P = primes.length;
    // factor[j][i] = exponent of primes[i] in j
    const factor = Array.from({ length: N + 1 }, () => new Array(P).fill(0));

    for (let i = 0; i < P; i++) {
        const p = primes[i];
        for (let pp = p; pp <= N; pp *= p) {
            for (let j = pp; j <= N; j += pp) {
                factor[j][i]++;
            }
        }
    }

    // Prefix sum to get factorials
    for (let j = 1; j <= N; j++) {
        for (let i = 0; i < P; i++) {
            factor[j][i] += factor[j - 1][i];
        }
    }

    function comb(m, n) {
        // m <= n assumed
        let res = 1; // w=0 term
        // fnm = factor[n] + factor[m]
        const fnm = factor[n].map((val, idx) => val + factor[m][idx]);

        for (let w = 1; w <= m; w++) {
            let r = 1;
            for (let i = 0; i < P; i++) {
                const pw = fnm[i] - factor[w][i] - factor[n - w][i] - factor[m - w][i];
                if (pw > 0) {
                    let base = primes[i];
                    let exp = pw;
                    let cur = 1;
                    while (exp > 0) {
                        if (exp & 1) cur = (cur * base) % MOD;
                        base = (base * base) % MOD;
                        exp >>= 1;
                    }
                    r = (r * cur) % MOD;
                }
            }
            res = (res + r) % MOD;
        }
        return res;
    }

    const ans = comb(abc[0], abc[1]) * comb(abc[0], abc[2]) % MOD * comb(abc[1], abc[2]) % MOD;
    console.log(ans);
}

main();
